selector_to_html = {"a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.fan_origin\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.fan_origin\">\n<span class=\"sig-name descname\"><span class=\"pre\">fan_origin</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A point each section is star-shaped about, in <code class=\"docutils literal notranslate\"><span class=\"pre\">(u,</span> <span class=\"pre\">v)</span></code> [m].</p><p>Every boundary point is visible from it, so a triangle fan to the\nboundary is a valid triangulation of the section. Meshing uses this to\ncap the ends of a swept passage. The default is the area centroid,\nwhich is correct for a convex family; a section with a reentrant\nboundary must override it.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.perimeter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.perimeter\">\n<span class=\"sig-name descname\"><span class=\"pre\">perimeter</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wetted</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Boundary length [m].</p><p>With <code class=\"docutils literal notranslate\"><span class=\"pre\">wetted</span></code> set, the inlet slot mouth is excluded, since it is an\nopening into the feeding passage rather than a wall.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.radial_profile\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.radial_profile\">\n<span class=\"sig-name descname\"><span class=\"pre\">radial_profile</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angles</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">samples</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">720</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Distance from <a class=\"reference internal\" href=\"#pyskyfire.ducts.volute_section.VoluteSection.fan_origin\" title=\"pyskyfire.ducts.volute_section.VoluteSection.fan_origin\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">fan_origin()</span></code></a> to the boundary at each angle [m].</p><p>The section is star-shaped about that origin, so the boundary is a\nsingle-valued <code class=\"docutils literal notranslate\"><span class=\"pre\">r(psi)</span></code> about it. That is what lets an exit cone morph\na section into a circle: blend this radius toward a constant one.</p></dd>", "a[href=\"#pyskyfire-ducts-volute-section-volutesection\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.volute_section.VoluteSection<a class=\"headerlink\" href=\"#pyskyfire-ducts-volute-section-volutesection\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.centroid_offset\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.centroid_offset\">\n<span class=\"sig-name descname\"><span class=\"pre\">centroid_offset</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Area-centroid distance outboard of the inlet plane [m].</p><p>The volute mean radius <code class=\"docutils literal notranslate\"><span class=\"pre\">r_c</span></code> of Aungier\u2019s design equation is the\ninlet radius plus this offset.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VoluteSection</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>A volute cross-section family with a fixed inlet slot width.</p><p>Subclasses define a shape parameterised by a positive <code class=\"docutils literal notranslate\"><span class=\"pre\">size</span></code> and an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">aspect</span></code>. All methods accept a scalar or a one-dimensional array of\nsizes, and return matching arrays; <code class=\"docutils literal notranslate\"><span class=\"pre\">aspect</span></code> defaults to the family\u2019s own\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">aspect_ratio</span></code> where it is not given.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.minimum_size\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.minimum_size\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">minimum_size</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Smallest <code class=\"docutils literal notranslate\"><span class=\"pre\">size</span></code> that still yields a valid section [m].</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.maximum_size\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.maximum_size\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">maximum_size</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Largest <code class=\"docutils literal notranslate\"><span class=\"pre\">size</span></code> the family can build [m].</p><p>Unbounded for a family that can simply keep growing. A section measured\nagainst something finite \u2013 a manifold\u2019s section has only so much\nchamber wall to spread onto \u2013 reports that limit here, so a law asking\nfor more area than exists is told so rather than being chased past the\nend of the geometry.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.boundary\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">abstractmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Counterclockwise boundary pieces for each size and aspect.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.polygon\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.polygon\">\n<span class=\"sig-name descname\"><span class=\"pre\">polygon</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">64</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Sampled closed boundary for plotting.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection._sizes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection._sizes\">\n<span class=\"sig-name descname\"><span class=\"pre\">_sizes</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Broadcast <code class=\"docutils literal notranslate\"><span class=\"pre\">size</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">aspect</span></code> into a matching pair of arrays.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.metrics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.metrics\">\n<span class=\"sig-name descname\"><span class=\"pre\">metrics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return <code class=\"docutils literal notranslate\"><span class=\"pre\">(area,</span> <span class=\"pre\">centroid,</span> <span class=\"pre\">lengths)</span></code> for each size and aspect.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.VoluteSection.area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.VoluteSection.area\">\n<span class=\"sig-name descname\"><span class=\"pre\">area</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Enclosed passage area [m^2].</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
